<?php
namespace Certloom\Infrastructure\Admin;

use Certloom\Domain\Job\JobStates;
use Certloom\Domain\Job\JobTypes;
use Certloom\Infrastructure\Job\JobRuntime;

/** Premium immutable-Version email preview, queue, status, retry and template workflow. */
final class EmailDeliveryAdmin {
	const PAGE='certloom-email-delivery'; const NOTICE='certloom_email_notice_';
	/** @var JobRuntime */ private $runtime;
	public function __construct(JobRuntime$runtime){$this->runtime=$runtime;}
	public function register(){add_action('admin_menu',array($this,'menu'),40);add_action('admin_post_certloom_email_preview',array($this,'preview_action'));add_action('admin_post_certloom_email_send',array($this,'send_action'));add_action('admin_post_certloom_email_retry',array($this,'retry_action'));add_action('admin_post_certloom_email_template_save',array($this,'save_template'));}
	public function menu(){add_submenu_page('certloom',__('Email Delivery','certloom'),__('Email Delivery','certloom'),\Ecapla_CertVerify_Permissions::CAP_MANAGE_CREDENTIALS,self::PAGE,array($this,'render'));}
	public function render(){ $this->cap();$version=isset($_GET['version_id'])?absint($_GET['version_id']):0;$preview_token=isset($_GET['email_preview'])?sanitize_text_field(wp_unslash($_GET['email_preview'])):'';echo '<div class="wrap certloom-shell certloom-email-delivery"><div class="certloom-page-head"><div><span class="certloom-eyebrow">'.esc_html__('WordPress-local delivery','certloom').'</span><h1>'.esc_html__('Email Delivery','certloom').'</h1><p>'.esc_html__('Preview a credential email before sending it through your WordPress mail setup. Certloom keeps the reviewed message only briefly and stores a minimal delivery history.','certloom').'</p></div><span class="certloom-domain-preview-badge">'.esc_html__('Credential preview','certloom').'</span></div>';$this->notice();echo '<div class="notice notice-warning inline"><p><strong>'.esc_html__('Availability:','certloom').'</strong> '.esc_html__('Public verification from the new credential store and PDF attachments are not enabled in this build yet. Certloom will not attach an unapproved certificate file or link to an unavailable verification experience.','certloom').'</p></div>';
		$this->composer($version,$preview_token);$this->template_form();$this->history();echo '</div>'; }
	public function preview_action(){ $this->cap();check_admin_referer('certloom_email_preview');$v=absint($_POST['version_id']??0);$to=isset($_POST['destination'])?sanitize_email(wp_unslash($_POST['destination'])):'';$kind=isset($_POST['delivery_kind'])?sanitize_key(wp_unslash($_POST['delivery_kind'])):'issued';if(!in_array($kind,array('issued','resend','test'),true)){$this->fail(__('That email delivery type is invalid.','certloom'),$v);}$review=$this->runtime->email_delivery()->preview($v,$to);if(is_wp_error($review)){$this->fail($review->get_error_message(),$v);}try{$token=bin2hex(random_bytes(16));}catch(\Throwable$e){$this->fail(__('Certloom could not create the email review token.','certloom'),$v);}set_transient('certloom_email_preview_'.$token.'_'.get_current_user_id(),array('version_id'=>$v,'destination'=>$review['destination'],'delivery_kind'=>$kind,'composition_sha256'=>$review['composed']['composition_sha256']),300);wp_safe_redirect(add_query_arg(array('page'=>self::PAGE,'version_id'=>$v,'email_preview'=>$token),admin_url('admin.php')));exit;}
	public function send_action(){ $this->cap();$token=isset($_POST['email_preview'])?sanitize_text_field(wp_unslash($_POST['email_preview'])):'';check_admin_referer('certloom_email_send_'.$token);$key='certloom_email_preview_'.$token.'_'.get_current_user_id();$saved=get_transient($key);delete_transient($key);if(!is_array($saved)){$this->fail(__('That email review expired. Preview the message again before sending.','certloom'));}$review=$this->runtime->email_delivery()->preview(absint($saved['version_id']),$saved['destination']);if(is_wp_error($review)||!hash_equals((string)($saved['composition_sha256']??''),is_wp_error($review)?'':(string)$review['composed']['composition_sha256'])){$this->fail(__('The credential email changed after review. Preview it again before sending.','certloom'),absint($saved['version_id']));}$job=$this->runtime->email_delivery()->enqueue(absint($saved['version_id']),$saved['destination'],get_current_user_id(),(string)($saved['delivery_kind']??'issued'),true);if(is_wp_error($job)){$this->fail($job->get_error_message(),absint($saved['version_id']));}$this->success(__('Credential email is being sent through WordPress.','certloom'));wp_safe_redirect(add_query_arg(array('page'=>self::PAGE,'version_id'=>absint($saved['version_id'])),admin_url('admin.php')));exit;}
	public function retry_action(){ $this->cap();$job=isset($_POST['job_key'])?strtolower(sanitize_text_field(wp_unslash($_POST['job_key']))):'';check_admin_referer('certloom_email_retry_'.$job);$row=$this->runtime->repository()->find($job);if(is_wp_error($row)||!is_array($row)||JobTypes::EMAIL_DELIVERY!==(string)($row['job_type']??'')||absint($row['owner_user_id']??0)!==get_current_user_id()){$this->fail(__('That Email Delivery job is unavailable or belongs to another administrator.','certloom'));}$retry=$this->runtime->retry_failed($job);if(is_wp_error($retry)){$this->fail($retry->get_error_message());}$this->success(__('The failed Email Delivery job was explicitly requeued.','certloom'));$this->go();}
	public function save_template(){ $this->cap();check_admin_referer('certloom_email_template_save');$template=array('subject'=>isset($_POST['subject'])?wp_unslash($_POST['subject']):'','html_body'=>isset($_POST['html_body'])?wp_unslash($_POST['html_body']):'','text_body'=>isset($_POST['text_body'])?wp_unslash($_POST['text_body']):'');$saved=$this->runtime->email_delivery()->save_template($template);if(is_wp_error($saved)){$this->fail($saved->get_error_message());}$this->success(__('Credential email template saved. Existing issued credential snapshots remain unchanged.','certloom'));$this->go();}
	private function composer($version,$token){$review=null;$saved=null;if(''!==$token){$saved=get_transient('certloom_email_preview_'.$token.'_'.get_current_user_id());if(is_array($saved)){$review=$this->runtime->email_delivery()->preview(absint($saved['version_id']),$saved['destination']);}}echo '<section class="certloom-manual-card certloom-email-card"><div class="certloom-manual-card-head"><div><span class="certloom-eyebrow">'.esc_html__('Step 1','certloom').'</span><h2>'.esc_html__('Preview credential email','certloom').'</h2></div><span class="certloom-template-state">'.esc_html__('Review before sending','certloom').'</span></div><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="certloom-manual-form"><input type="hidden" name="action" value="certloom_email_preview">';wp_nonce_field('certloom_email_preview');echo '<div class="certloom-manual-grid certloom-manual-grid-2"><label><span>'.esc_html__('Credential Version ID','certloom').'</span><input type="number" min="1" required name="version_id" value="'.esc_attr($version?:'').'"></label><label><span>'.esc_html__('Destination email','certloom').'</span><input type="email" name="destination" value="'.esc_attr(is_array($saved)?(string)$saved['destination']:'').'" placeholder="'.esc_attr__('Uses the saved recipient email when blank','certloom').'"></label></div><div class="certloom-manual-choice-row"><label><input type="radio" name="delivery_kind" value="issued" '.checked(!is_array($saved)||'issued'===(string)($saved['delivery_kind']??'issued'),true,false).'> '.esc_html__('Issued credential','certloom').'</label><label><input type="radio" name="delivery_kind" value="resend" '.checked(is_array($saved)&&'resend'===(string)($saved['delivery_kind']??''),true,false).'> '.esc_html__('Resend','certloom').'</label><label><input type="radio" name="delivery_kind" value="test" '.checked(is_array($saved)&&'test'===(string)($saved['delivery_kind']??''),true,false).'> '.esc_html__('Test delivery','certloom').'</label></div><div class="certloom-manual-actions"><button class="button button-primary button-hero" type="submit">'.esc_html__('Preview email','certloom').'</button><span>'.esc_html__('Preview does not send the email or change the credential.','certloom').'</span></div></form>';
		if(is_wp_error($review)){$this->error($review->get_error_message());}elseif(is_array($review)&&is_array($saved)){ $c=$review['composed'];echo '<div class="certloom-email-preview"><div class="certloom-template-preview-proof"><div><span>'.esc_html__('Composition SHA-256','certloom').'</span><code>'.esc_html((string)$c['composition_sha256']).'</code></div><div><span>'.esc_html__('Destination','certloom').'</span><code>'.esc_html((string)$review['destination_mask']).'</code></div><div><span>'.esc_html__('Delivery kind','certloom').'</span><code>'.esc_html((string)($saved['delivery_kind']??'issued')).'</code></div></div><div class="certloom-email-preview-subject"><strong>'.esc_html__('Subject','certloom').'</strong><p>'.esc_html((string)$c['subject']).'</p></div><div class="certloom-email-preview-body">'.wp_kses_post((string)$c['html_body']).'</div><details><summary>'.esc_html__('Plain-text fallback','certloom').'</summary><pre>'.esc_html((string)$c['text_body']).'</pre></details><div class="notice notice-info inline"><p>'.esc_html__('This review is tied to the current credential and email template. If either changes, Certloom will ask you to preview again before sending.','certloom').'</p></div><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="certloom_email_send"><input type="hidden" name="email_preview" value="'.esc_attr($token).'">';wp_nonce_field('certloom_email_send_'.$token);echo '<button class="button button-primary button-hero" type="submit">'.esc_html__('Send reviewed email','certloom').'</button></form></div>';}
		echo '</section>';}
	private function template_form(){$t=$this->runtime->email_delivery()->template();echo '<section class="certloom-manual-card certloom-email-template"><div class="certloom-manual-card-head"><div><span class="certloom-eyebrow">'.esc_html__('Versioned template v1','certloom').'</span><h2>'.esc_html__('Issued-credential email template','certloom').'</h2></div></div><p>'.esc_html__('This template is stored in WordPress. Each email uses the saved details from the issued credential so later profile or design changes do not rewrite the original message data.','certloom').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="certloom_email_template_save">';wp_nonce_field('certloom_email_template_save');echo '<label class="certloom-email-field"><span>'.esc_html__('Subject','certloom').'</span><input class="large-text" maxlength="200" name="subject" value="'.esc_attr((string)$t['subject']).'"></label><label class="certloom-email-field"><span>'.esc_html__('HTML body','certloom').'</span><textarea class="large-text code" rows="8" name="html_body">'.esc_textarea((string)$t['html_body']).'</textarea></label><label class="certloom-email-field"><span>'.esc_html__('Plain-text fallback','certloom').'</span><textarea class="large-text code" rows="8" name="text_body">'.esc_textarea((string)$t['text_body']).'</textarea></label><p class="description">'.esc_html__('Tokens: {{recipient_name}}, {{program_title}}, {{issuer_name}}, {{credential_number}}, {{issue_date}}, {{expiry_date}}, {{grade}}, {{verification_url}}, {{verification_link}}.','certloom').'</p>';submit_button(__('Save email template','certloom'),'secondary','submit',false);echo '</form></section>';}
	private function history(){$rows=$this->runtime->email_delivery()->recent(50);echo '<section class="certloom-manual-card certloom-email-history"><div class="certloom-manual-card-head"><div><span class="certloom-eyebrow">'.esc_html__('Delivery history','certloom').'</span><h2>'.esc_html__('Recent deliveries','certloom').'</h2></div></div>';if(is_wp_error($rows)){$this->error($rows->get_error_message());echo'</section>';return;}echo '<div class="certloom-domain-table-wrap"><table class="widefat striped"><thead><tr><th>'.esc_html__('Version','certloom').'</th><th>'.esc_html__('Destination','certloom').'</th><th>'.esc_html__('Kind','certloom').'</th><th>'.esc_html__('Status','certloom').'</th><th>'.esc_html__('Attempted','certloom').'</th><th>'.esc_html__('Action','certloom').'</th></tr></thead><tbody>';foreach($rows as$r){$status=(string)($r['status']??'');echo'<tr><td>#'.esc_html((string)absint($r['version_id']??0)).'</td><td><code>'.esc_html((string)($r['destination_mask']??'')).'</code></td><td>'.esc_html((string)($r['delivery_kind']??'')).'</td><td><span class="certloom-email-status is-'.esc_attr(sanitize_html_class($status)).'">'.esc_html($status).'</span>';if('uncertain'===$status){echo'<p class="description">'.esc_html__('Do not auto-retry. The external outcome is unknown.','certloom').'</p>';}echo'</td><td>'.esc_html((string)($r['attempted_at']??'—')).'</td><td>';$owner=absint($r['evidence']['requested_by']??0);if('failed'===$status&&!empty($r['job_key'])&&$owner===get_current_user_id()){echo'<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="certloom_email_retry"><input type="hidden" name="job_key" value="'.esc_attr((string)$r['job_key']).'">';wp_nonce_field('certloom_email_retry_'.(string)$r['job_key']);echo'<button class="button button-small">'.esc_html__('Retry failed','certloom').'</button></form>';}elseif('failed'===$status&&!empty($r['job_key'])){echo'<span class="description">'.esc_html__('Retry is available to the administrator who started this delivery.','certloom').'</span>';}elseif('uncertain'===$status){echo'<a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>self::PAGE,'version_id'=>absint($r['version_id']??0)),admin_url('admin.php'))).'">'.esc_html__('Review resend','certloom').'</a>';}else{echo'—';}echo'</td></tr>';}if(empty($rows)){echo'<tr><td colspan="6">'.esc_html__('No credential emails have been sent yet.','certloom').'</td></tr>';}echo'</tbody></table></div></section>';}
	private function cap(){if(!current_user_can(\Ecapla_CertVerify_Permissions::CAP_MANAGE_CREDENTIALS)){wp_die(esc_html__('You do not have permission to deliver Certloom credential email.','certloom'));}}
	private function go(){wp_safe_redirect(admin_url('admin.php?page='.self::PAGE));exit;}private function fail($m,$v=0){$this->store('error',$m);wp_safe_redirect(add_query_arg(array('page'=>self::PAGE,'version_id'=>$v?:null),admin_url('admin.php')));exit;}private function success($m){$this->store('success',$m);}private function store($t,$m){set_transient(self::NOTICE.get_current_user_id(),array('type'=>$t,'message'=>(string)$m),120);}private function notice(){$k=self::NOTICE.get_current_user_id();$n=get_transient($k);if(!is_array($n)||empty($n['message']))return;delete_transient($k);echo'<div class="notice '.('success'===($n['type']??'')?'notice-success':'notice-error').' is-dismissible"><p>'.esc_html((string)$n['message']).'</p></div>';}private function error($m){echo'<div class="notice notice-error inline"><p>'.esc_html((string)$m).'</p></div>';}
}
